const paperFrame=document.querySelector('#paperFrame');let selectedPaper=null,paperReady=false;
const paperNames={study:'自习室',library:'图书馆',canteen:'食堂',seminar:'研讨室',class:'课堂',shop:'小卖部',games:'娱乐室'};
document.querySelector('#paperLinks').innerHTML=Object.entries(paperNames).map(([id,name],i)=>`<button data-paper="${id}"><small>0${i+1} / EXPLORE</small>${name} ↗</button>`).join('');
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
document.querySelectorAll('[data-paper]').forEach(b=>b.onclick=()=>{if(!paperReady||reduced){enter(b.dataset.paper);return}paperFrame.contentWindow.postMessage({type:'campus-select',id:b.dataset.paper},location.origin)});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==paperFrame.contentWindow)return;if(e.data.type==='campus-paper-ready'){paperReady=true;document.querySelector('.paper-stage').classList.add('ready')}if(e.data.type==='campus-paper-open'&&paperNames[e.data.id]){selectedPaper=e.data.id;document.querySelector('#paperName').textContent=paperNames[selectedPaper];document.querySelector('#paperAction').hidden=false;document.querySelectorAll('[data-paper]').forEach(b=>b.classList.toggle('active',b.dataset.paper===selectedPaper))}if(e.data.type==='campus-paper-close')document.querySelector('#paperAction').hidden=true});
document.querySelector('#enterPaper').onclick=()=>{if(selectedPaper)enter(selectedPaper)};document.querySelector('#foldPaper').onclick=()=>paperFrame.contentWindow.postMessage({type:'campus-fold'},location.origin);document.querySelector('#showMap').onclick=()=>{const map=document.querySelector('.map-section');map.hidden=!map.hidden;document.querySelector('#showMap').textContent=map.hidden?'校园地图 ↗':'收起地图 ↑';if(!map.hidden)map.scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'})};
setTimeout(()=>{if(!paperReady)document.querySelector('#paperFallback').textContent='3D 纸张尚未加载完成，可以使用下方入口，或切换校园地图。'},12000);
